from pymisp import MISPObject


def build_misp_object(misp_object: MISPObject, data) -> dict:
    misp_object.add_attribute(object_relation='minimumFcrClicks', type='integer', value=data.get("minimumFcrClicks"))
    misp_object.add_attribute(object_relation='fcgPaths', type='text', value=data.get("fcgPaths"))
    misp_object.add_attribute(object_relation='fcrPaths', type='text', value=data.get("fcrPaths"))
    misp_object.add_attribute(object_relation='canNavigate', type='boolean', value=data.get("canNavigate"))
    misp_object.add_attribute(object_relation='fcgDuration', type='float', value=data.get("fcgDuration"))
    misp_object.add_attribute(object_relation='fcrDuration', type='float', value=data.get("fcrDuration"))
    misp_object.add_attribute(object_relation='acceptButtonSize', type='float', value=data.get("acceptButtonSize"))
    misp_object.add_attribute(object_relation='rejectButtonSize', type='float', value=data.get("rejectButtonSize"))
    misp_object.add_attribute(object_relation='optionButtonSize', type='float', value=data.get("optionButtonSize"))
    misp_object.add_attribute(object_relation='acceptButtonColor', type='text', value=data.get("acceptButtonColor"))
    misp_object.add_attribute(object_relation='rejectButtonColor', type='text', value=data.get("rejectButtonColor"))
    misp_object.add_attribute(object_relation='optionButtonColor', type='text', value=data.get("optionButtonColor"))
    misp_object.add_attribute(object_relation='textOfTheAcceptButton', type='text', value=data.get("textOfTheAcceptButton"))
    misp_object.add_attribute(object_relation='textOfTheRejectButton', type='text', value=data.get("textOfTheRejectButton"))
    misp_object.add_attribute(object_relation='textOfTheOptionButton', type='text', value=data.get("textOfTheOptionButton"))
    misp_object.add_attribute(object_relation='bannerSize', type='float', value=data.get("bannerSize"))
    misp_object.add_attribute(object_relation='hasCCImage', type='boolean', value=data.get("hasCCImage"))
    misp_object.add_attribute(object_relation='hasFCRIcon', type='boolean', value=data.get("hasFCRIcon"))
    misp_object.add_attribute(object_relation='hasFCGIcon', type='boolean', value=data.get("hasFCGIcon"))
    misp_object.add_attribute(object_relation='privacyPolicyLinkPresent', type='boolean', value=data.get("privacyPolicyLinkPresent"))
    misp_object.add_attribute(object_relation='availabilityOfFCGProcess', type='boolean', value=data.get("availabilityOfFCGProcess"))
    misp_object.add_attribute(object_relation='availabilityOfFCRProcess', type='boolean', value=data.get("availabilityOfFCRProcess"))
    misp_object.add_attribute(object_relation='fcgFontType', type='text', value=data.get("fcgFontType"))
    misp_object.add_attribute(object_relation='fcrFontType', type='text', value=data.get("fcrFontType"))
    misp_object.add_attribute(object_relation='fcgFontSize', type='float', value=data.get("fcgFontSize"))
    misp_object.add_attribute(object_relation='fcrFontSize', type='float', value=data.get("fcrFontSize"))
    misp_object.add_attribute(object_relation='fcgFontWeight', type='integer', value=data.get("fcgFontWeight"))
    misp_object.add_attribute(object_relation='fcrFontWeight', type='integer', value=data.get("fcrFontWeight"))
    misp_object.add_attribute(object_relation='bannerTextContent', type='text', value=data.get("bannerTextContent"))
    misp_object.add_attribute(object_relation='asymmetric', type='boolean', value=data.get("asymmetric"))
    misp_object.add_attribute(object_relation='restrictive', type='boolean', value=data.get("restrictive"))
    misp_object.add_attribute(object_relation='datetime', type='datetime', value=data.get("datetime"))
    misp_object.add_attribute(object_relation='covert', type='boolean', value=data.get("covert"))
    misp_object.add_attribute(object_relation='darkPattern', type='boolean', value=data.get("darkPattern"))
    misp_object.add_attribute(object_relation='deceptive', type='boolean', value=data.get("deceptive"))
    misp_object.add_attribute(object_relation='hiddenInformation', type='boolean', value=data.get("hiddenInformation"))
    misp_object.add_attribute(object_relation='covertRulesMatched', type='text', value=data.get("covertRulesMatched"))
    misp_object.add_attribute(object_relation='restrictiveRulesMatched', type='text', value=data.get("restrictiveRulesMatched"))
    misp_object.add_attribute(object_relation='asymmetricRulesMatched', type='text', value=data.get("asymmetricRulesMatched"))
    misp_object.add_attribute(object_relation='deceptiveRulesMatched', type='text', value=data.get("deceptiveRulesMatched"))
    misp_object.add_attribute(object_relation='hiddenInformationRulesMatched', type='text', value=data.get("hiddenInformationRulesMatched"))

    return misp_object